`timescale 1ns / 1ps

module tb_lab1;
    reg clk, rst;
    wire [31:0] debug_data;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'd0),
        .debug_data(debug_data),
        .clk(clk),
        .rst(rst),
        .interrupter(1'b0)
    );

    initial begin
        clk = 0;
        rst = 1;
        #2 rst = 0;
    end
    always #1 clk = ~clk;

    integer cycle = 0;
    // log every WB-stage register write-back
    always @(posedge clk) begin
        if (!rst) begin
            cycle = cycle + 1;
            if (core.RegWrite_WB && core.rd_WB != 0)
                $display("cyc %0d: WB pc=%h x%0d = %h", cycle, core.PC_WB, core.rd_WB, core.wt_data_WB);
            if (cycle > 400) begin
                $display("TIMEOUT / done after %0d cycles", cycle);
                $finish;
            end
        end
    end

    // stop once the final jalr (pc=0x128) has been written back, plus some slack
    reg seen_jalr = 0;
    integer tail = 0;
    always @(posedge clk) begin
        if (!rst && core.RegWrite_WB && core.PC_WB == 32'h128) seen_jalr <= 1;
        if (seen_jalr) begin
            tail = tail + 1;
            if (tail > 10) begin
                $display("FINISHED: full pass of all_test.s observed");
                $finish;
            end
        end
    end
endmodule

